// Kinds of custom task an owner or manager can create
// Vaccination and treatment are NEVER generated by PoultryStart (Evidence-Based

const VET_PLAN_DISCLAIMER =
  'PoultryStart does not create vaccination schedules or give medicine doses. ' +
  'Follow your veterinarian or your chick supplier\'s programme.';

const CUSTOM_TASK_TYPES = Object.freeze({
  general: { code: 'TC-01', label: 'Custom task' },
  vet_plan: {
    code: 'TC-02',
    label: 'Vet or supplier plan reminder',
    help: 'Enter the vaccination or treatment exactly as your vet\'s or chick supplier\'s programme states.',
    disclaimer: VET_PLAN_DISCLAIMER,
  },
  sale_preparation: { code: 'TC-03', label: 'Sale preparation (no expected sale date entered)' },
});

const DEFAULT_CUSTOM_TASK_TYPE = 'general';

const customTypeOfCode = (code) =>
  Object.keys(CUSTOM_TASK_TYPES).find((type) => CUSTOM_TASK_TYPES[type].code === code) || null;

module.exports = { CUSTOM_TASK_TYPES, DEFAULT_CUSTOM_TASK_TYPE, VET_PLAN_DISCLAIMER, customTypeOfCode };
